# EMPLEADOS_IA - Instalar B1 en D:\EMPLEADOS_IA
# Ejecutar en PowerShell: Set-ExecutionPolicy -Scope Process Bypass; D:\EMPLEADOS_IA\INSTALAR_B1_EN_D.ps1
$ErrorActionPreference = "Stop"
$Root = if ($PSScriptRoot) { $PSScriptRoot } else { "D:\EMPLEADOS_IA" }
Set-Location $Root
$b64 = @'

'@
$zip = Join-Path $env:TEMP "eaios_b1.zip"
[IO.File]::WriteAllBytes($zip, [Convert]::FromBase64String(($b64 -replace "`r","" -replace "`n","")))
Add-Type -AssemblyName System.IO.Compression.FileSystem
[System.IO.Compression.ZipFile]::ExtractToDirectory($zip, $Root)
Write-Host "[OK] B1 extraido en $Root"
Write-Host "Siguiente: .\CREAR_ENTORNO.bat  luego  .\ARRANCAR.bat"
Write-Host "Web: http://127.0.0.1:5180  login admin / Admin2026*"
